+ * parent at that point is a server-rendered element being hydrated.
+ * The user may have interacted with it before hydration (e.g. on a slow
+ * connection), in which case its live state no longer matches the state
+ * described by its HTML attributes and must be preserved.
+ */
+function isUserModifiedBeforeHydration(
+  el: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement,
+): boolean {
+  if (!el.parentNode) return false
+  switch (el.tagName) {
+    case 'TEXTAREA':
+      return (
+        (el as HTMLTextAreaElement).value !==
+        (el as HTMLTextAreaElement).defaultValue
+      )
+    case 'SELECT':
+      return isSelectModified(el as HTMLSelectElement)
+    case 'INPUT':
+      return isInputModified(el as HTMLInputElement)
+    default:
+      return false
+  }
+}
+
+function isInputModified(el: HTMLInputElement): boolean {
+  if (el.type === 'checkbox' || el.type === 'radio') {
+    return el.checked !== el.defaultChecked
